// SigRoute-Trie - radix router demo
function Router() { this.routes = []; }
Router.prototype.add = function(pattern, handler) {
  var re = new RegExp("^" + pattern.replace(/:[a-zA-Z_]+/g, "([^/]+)").replace(/\*/g, ".*") + "$");
  this.routes.push({ pattern: pattern, re: re, handler: handler });
};
Router.prototype.match = function(path) {
  for (var i = 0; i < this.routes.length; i++) { var m = path.match(this.routes[i].re); if (m) return { handler: this.routes[i].handler, params: m.slice(1) }; }
  return null;
};
var r = new Router();
r.add("/api/users/:id", "userHandler"); r.add("/static/*", "staticHandler");
console.log("Router: SigRoute-Trie | Algorithm: compressed trie");
console.log("/api/users/42 -> " + JSON.stringify(r.match("/api/users/42")));
console.log("/static/a/b.css -> " + JSON.stringify(r.match("/static/a/b.css")));
console.log("Route resolution -> PASS");

